    param(
        [Parameter(Mandatory=$true)]
        [string]$JsonString
    )

    $config = $JsonString | ConvertFrom-Json

    return @{}

    function Build-NestedHash {
        param([hashtable]$CurrentHash, [object]$JsonNode)
