using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public class WordFrequency
{
    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: WordFrequency <filename>");
            return;
        }

        string filePath = args[0];

        if (!File.Exists(filePath))
        {
            Console.WriteLine($"Error: File not found at {filePath}");
            return;
        }

        try
        {
            string content = File.ReadAllText(filePath);
            // Simple tokenization: convert to lowercase and split by non-word characters
            var words = content.ToLower().Split(new char[] { ' ', '\r', '\n', ',', '.', '!', '?', ':', ';', '(', ')', '-', '/', '[', ']' }, StringSplitOptions.RemoveEmptyEntries);

            // Filter out empty strings and short words (optional, but good practice)
            var meaningfulWords = words.Where(w => w.Length > 1).ToList();

            // Count word frequencies
            var wordCounts = meaningfulWords
                .GroupBy(word => word)
                .Select(g => new { Word = g.Key, Count = g.Count() })
                .OrderByDescending(x => x.Count)
                .Take(10);

            Console.WriteLine("Top 10 Most Frequent Words:");
            foreach (var item in wordCounts)
            {
                Console.WriteLine($"{item.Word}: {item.Count}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
