using System;
using System.IO;
using System.Threading.Tasks;

public class Program
{
    public static async Task Main(string[] args)
    {
        // Create dummy files for testing if they don't exist
        File.WriteAllText("file1.txt", "This is the content of file one.");
        File.WriteAllText("file2.txt", "This is the content of file two, which is slightly longer.");

        try
        {
            var task1 = ReadFileSizeAsync("file1.txt");
            var task2 = ReadFileSizeAsync("file2.txt");

            await Task.WhenAll(task1, task2);

            Console.WriteLine($"Length of file1.txt: {task1.Result}");
            Console.WriteLine($"Length of file2.txt: {task2.Result}");
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"Error: One or both files were not found. {ex.Message}");
        }
    }

    public static async Task<long> ReadFileSizeAsync(string path)
    {
        using (var stream = new FileStream(path, FileMode.Open, FileAccess.Read))
        {
            // Use a small buffer to read the entire file size efficiently
            return await Task.Run(() => stream.Length);
        }
    }
}
