using System;
using System.Collections.Generic;

public class ThreadSafeLruCache<T> where T : class
{
    private readonly int _capacity;
    private readonly Dictionary<object, LinkedListNode<object>> _cacheMap;
    private readonly LinkedList<object> _lruList;
    private readonly object _lock = new object();

    public ThreadSafeLruCache(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _capacity = capacity;
        _cacheMap = new Dictionary<object, LinkedListNode<object>>();
        _lruList = new LinkedList<object>();
    }

    public T Get(object key)
    {
        lock (_lock)
        {
            if (!_cacheMap.TryGetValue(key, out var node))
            {
                return default(T);
            }

            // Move the accessed node to the front (most recently used)
            _lruList.Remove(node);
            _lruList.AddFirst(node);

            return (T)node.Value;
        }
    }

    public void Put(object key, T value)
    {
        lock (_lock)
        {
            if (_cacheMap.ContainsKey(key))
            {
                // Update existing item and move to front
                var node = _cacheMap[key];
                node.Value = value;
                _lruList.Remove(node);
                _lruList.AddFirst(node);
            }
            else if (_cacheMap.Count >= _capacity)
            {
                // Evict LRU item (least recently used)
                var lruNode = _lruList.Last;
                if (lruNode != null)
                {
                    _lruList.RemoveLast();
                    _cacheMap.Remove(lruNode.Value as object);
                }
            }

            // Add new item
            var newNode = _lruList.AddFirst(new LinkedListNode<object>(value));
            _cacheMap[key] = newNode;
        }
    }
}

public class Program
{
    public static void Main()
    {
        ThreadSafeLruCache<string> cache = new ThreadSafeLruCache<string>(3);

        Console.WriteLine("--- Initial Puts ---");
        cache.Put("Key1", "Value1"); // Cache: [Key1]
        cache.Put("Key2", "Value2"); // Cache: [Key2, Key1]
        cache.Put("Key3", "Value3"); // Cache: [Key3, Key2, Key1]

        Console.WriteLine($"Get Key1: {cache.Get("Key1") ?? "Not Found"}"); // Access Key1 -> [Key1, Key3, Key2]
        Console.WriteLine($"Put Key4 (Evicts Key2):");
        cache.Put("Key4", "Value4"); // Cache: [Key4, Key1, Key3]

        Console.WriteLine($"Get Key2: {cache.Get("Key2") ?? "Not Found"}"); // Not Found
