        Console.WriteLine($"Put Key5 (Evicts Key1):");
        cache.Put("Key5", "Value5"); // Cache: [Key5, Key3, Key4]

        Console.WriteLine($"Get Key1: {cache.Get("Key1") ?? "Not Found"}"); // Not Found
    }
}
