using System;
using System.IO;
using System.Linq;

public class FileLister
{
    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FileLister <folderPath>");
            return;
        }

        string startPath = args[0];

        if (!Directory.Exists(startPath))
        {
            Console.WriteLine($"Error: Directory not found at {startPath}");
            return;
        }

        try
        {
            var largeFiles = GetLargeFilesRecursively(startPath, 100 * 1024 * 1024); // 100 MB in bytes

            if (largeFiles.Any())
            {
                Console.WriteLine("Files over 100MB found:");
                foreach (var fileInfo in largeFiles)
                {
                    Console.WriteLine($"{fileInfo.FullName} ({fileInfo.Length / (1024 * 1024)} MB)");
                }
            }
            else
            {
                Console.WriteLine("No files over 100MB found.");
            }
        }
        catch (UnauthorizedAccessException)
        {
            Console.WriteLine($"Access denied to one or more directories in {startPath}.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private static IEnumerable<FileInfo> GetLargeFilesRecursively(string path, long maxSize)
    {
        var files = new List<FileInfo>();
        try
        {
            // Get all files in the current directory
            var directoryItems = Directory.GetFileSystemEntries(path);

            foreach (string item in directoryItems)
            {
                if (File.Exists(item))
                {
                    FileInfo fileInfo = new FileInfo(item);
                    if (fileInfo.Length > maxSize)
                    {
                        files.Add(fileInfo);
                    }
                    // Recurse into subdirectories
                    var subDir = Path.Combine(path, item);
                    if (Directory.Exists(subDir))
                    {
                        files.AddRange(GetLargeFilesRecursively(subDir, maxSize));
                    }
                }
            }
        }
        catch (UnauthorizedAccessException)
        {
            // Continue processing other directories if access is denied to one
        }
        return files;
    }
}
