        Console.WriteLine("Press Enter to stop watching.");

        // Event handlers
        _watcher.Created += OnFileEvent;
        _watcher.Changed += OnFileEvent;
        _watcher.Deleted += OnFileEvent;
        _watcher.Renamed += OnFileEvent;

        while (true)
        {
            Console.ReadLine();
            break; // Exit loop when Enter is pressed
        }

        _watcher.EnableRaisingEvents = false;
    }

    private static void OnFileEvent(object sender, FileSystemEventArgs e)
    {
        string fileName = Path.GetFileName(e.FullPath);
        Console.WriteLine($"[{DateTime.Now:HH:mm:ss}] Event: {e.ChangeType} on file: {fileName}");
    }
