function Retry-ScriptBlock {
    param(
        [Parameter(Mandatory=$true)]
        [scriptblock]$ScriptBlock,

        [int]$MaxRetries = 3,

        [int]$DelaySeconds = 2
    )

    for ($i = 1; $i -le $MaxRetries; $i++) {
        try {
            & $ScriptBlock
            return # Success
        } catch {
            Write-Error "Attempt $($i) failed: $($_.Exception.Message)"
            if ($i -lt $MaxRetries) {
                Start-Sleep -Seconds $DelaySeconds
            }
        }
    }
    throw "Script block failed after $MaxRetries attempts."
}

