function Get-DuplicateFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [switch]$Recurse
    )

    Set-StrictMode -Version 2.0
    $ErrorActionPreference = 'Stop'

    if (-not (Test-Path -Path $Path)) {
        Write-Error "Path not found: $Path"
        return
    }

    $fileHashes = @{}

    Get-ChildItem -Path $Path -File -Recurse:$Recurse -ErrorAction SilentlyContinue | ForEach-Object {
        try {
            $hash = Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256
            $fileHashes[$hash.Hash] = @($_.FullName)
        } catch {
            Write-Warning "Could not hash file $($_.FullName): $($_.Exception.Message)"
        }
    }

    $duplicates = @()
    foreach ($hash in $fileHashes.Keys) {
        if ($fileHashes[$hash].Count -gt 1) {
            $duplicates += [PSCustomObject]@{
                Hash = $hash
                Files = $fileHashes[$hash]
            }
        }
    }

    if ($duplicates.Count -eq 0) {
        Write-Output "No duplicate files found."
    } else {
        $duplicates | Format-Table Hash, @{Name="File Count"; Expression={$_.Files.Count}}
    }
}
