using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Please provide a text file path as an argument.");
            return;
        }

        string filePath = args[0];
        string text = File.ReadAllText(filePath);

        Dictionary<string, int> counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        // Use Regex to find words (alphabetic characters)
        foreach (Match m in Regex.Matches(text, @"[A-Za-z']+"))
        {
            int n;
            if (counts.TryGetValue(m.Value, out n))
            {
                counts[m.Value] = n + 1;
            }
            else
            {
                counts[m.Value] = 1;
            }
        }

        // Order by count descending, then alphabetically ascending for ties (optional refinement)
        var topWords = counts.OrderByDescending(p => p.Value).ThenBy(p => p.Key).Take(10);

        foreach (KeyValuePair<string, int> kvp in topWords)
            Console.WriteLine("{0,-15} {1}", kvp.Key, kvp.Value);
    }
}
