using System;
using System.Collections.Generic;

class LruCache<TKey, TValue>
{
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<KeyValuePair<TKey, TValue>>> _map = new Dictionary<TKey, LinkedListNode<KeyValuePair<TKey, TValue>>>();
    private readonly LinkedList<KeyValuePair<TKey, TValue>> _order = new LinkedList<KeyValuePair<TKey, TValue>>();
    private readonly object _lock = new object();

    public LruCache(int capacity) { _capacity = capacity; }

    public bool TryGet(TKey key, out TValue value)
    {
        lock (_lock)
        {
            LinkedListNode<KeyValuePair<TKey, TValue>> node;
            if (!_map.TryGetValue(key, out node)) { value = default(TValue); return false; }
            _order.Remove(node); _order.AddFirst(node);
            value = node.Value.Value;
            return true;
        }
    }

    public void Put(TKey key, TValue value)
    {
        lock (_lock)
        {
            LinkedListNode<KeyValuePair<TKey, TValue>> old;
            if (_map.TryGetValue(key, out old)) { _order.Remove(old); _map.Remove(key); }
            else if (_map.Count >= _capacity) { _map.Remove(_order.Last.Value.Key); _order.RemoveLast(); }
            _map[key] = _order.AddFirst(new KeyValuePair<TKey, TValue>(key, value));
        }
    }
}

class Program
{
    static void Main(string[] args)
    {
        LruCache<string, int> cache = new LruCache<string, int>(2);
        cache.Put("a", 1);
        cache.Put("b", 2);
        cache.Put("c", 3);

        int value;
        if (cache.TryGet("a", out value))
        {
            Console.WriteLine("a found: " + value);
        }
        else
        {
            Console.WriteLine("a evicted");
        }

        if (!cache.TryGet("d", out value))
        {
            Console.WriteLine("d not found (expected)");
        }
    }
}
