function Retry-ScriptBlock {
    param(
        [Parameter(Mandatory=$true)]
        [scriptblock]
        [int]$MaxRetries = 3,

        [int]$RetryDelaySeconds = 2
    )

    for ($i = 1; $i -le $MaxRetries; $i++) {
        try {
            & $scriptblock
            Write-Verbose "Script block succeeded on attempt $i."
            return # Exit function on success
        }
        catch {
            Write-Error "Attempt $i failed. Error: $($_.Exception.Message)"
            if ($i -lt $MaxRetries) {
                Write-Warning "Retrying in $RetryDelaySeconds seconds..."
                Start-Sleep -Seconds $RetryDelaySeconds
            }
        }
    }
    Write-Error "Script block failed after $MaxRetries attempts."
}

