function ConvertFrom-JsonToNestedHashtable {
    param(
        [Parameter(Mandatory = $true)]
        [string]$JsonFilePath
    )

    try {
        # Read the JSON content from the file
        $jsonContent = Get-Content -Path $JsonFilePath -Raw

        # Convert the raw JSON string into a PowerShell object
        $jsonObject = ConvertFrom-Json -InputObject $jsonContent

        # Recursively convert the resulting object structure into a nested hashtable
        function ConvertToNestedHashtable {
            param(
                [Parameter(Mandatory = $true)]
                [object]$InputObject
            )
            if ($InputObject -is [System.Management.Automation.PSCustomObject]) {
                $h = @{}
                foreach ($p in $InputObject.PSObject.Properties) {
                    # Recursively call the function for each property value
                    $h[$p.Name] = ConvertToNestedHashtable -InputObject $p.Value
                }
                return $h
            } elseif ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) {
                # Handle arrays by converting each element recursively
                return @($InputObject | ForEach-Object { ConvertToNestedHashtable -InputObject $_ })
            } else {
                # Return primitive types as is
                return $InputObject
            }
        }

        $nestedHash = ConvertToNestedHashtable -InputObject $jsonObject
        Write-Output $nestedHash

    } catch {
        Write-Error ("Failed to convert JSON from file '$JsonFilePath': $($_.Exception.Message)")
    }
}
